<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register | AutoTrack</title><link rel="stylesheet" href="css/style.css"></head><body><div class="auth"><section class="auth-visual"><h1>Create your vehicle care account.</h1><p>Your mobile number is stored with your account so the backend can send maintenance reminders and appointment alerts through an SMS provider.</p></section><section class="auth-panel"><form class="auth-card" onsubmit="event.preventDefault();location.href='dashboard.html'"><h2>Create account</h2><div class="form-grid"><div class="field"><label>First name</label><input required></div><div class="field"><label>Last name</label><input required></div><div class="field full"><label>Email</label><input type="email" required></div><div class="field full"><label>Mobile number</label><input type="tel" placeholder="+94 77 123 4567" required><span class="hint">Used for SMS maintenance and booking alerts.</span></div><div class="field full"><label>Password</label><input type="password" required></div></div><button class="btn btn-primary full-btn">Create account</button><p class="footer-note">Already registered? <a href="login.html" style="color:#2563eb">Sign in</a></p></form></section></div></body></html>